import pytest
from algorithms import find_two_sum, longest_common_prefix, rotate_list


# --- two_sum ---
def test_two_sum_basic():
    result = find_two_sum([2, 7, 11, 15], 9)
    assert result is not None
    i, j = result
    assert i == 0 and j == 1


def test_two_sum_not_first_indices():
    result = find_two_sum([3, 2, 4], 6)
    assert result is not None
    i, j = sorted(result)
    assert i == 1 and j == 2


def test_two_sum_no_solution():
    assert find_two_sum([1, 2, 3], 10) is None


# --- longest_common_prefix ---
def test_lcp_basic():
    assert longest_common_prefix(["flower", "flow", "flight"]) == "fl"


def test_lcp_no_prefix():
    assert longest_common_prefix(["dog", "racecar", "car"]) == ""


def test_lcp_empty_list():
    assert longest_common_prefix([]) == ""


def test_lcp_shorter_string():
    assert longest_common_prefix(["ab", "a"]) == "a"


# --- rotate_list ---
def test_rotate_basic():
    assert rotate_list([1, 2, 3, 4, 5], 2) == [4, 5, 1, 2, 3]


def test_rotate_empty():
    assert rotate_list([], 3) == []


def test_rotate_k_zero():
    assert rotate_list([1, 2, 3], 0) == [1, 2, 3]


def test_rotate_large_k():
    assert rotate_list([1, 2, 3], 9) == [1, 2, 3]  # k=9 is same as k=0 for len 3
